package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueKindOptions;

class KindVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property kind of observed issue ")
  void test_kind_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom("_ERROR_"));
    Assertions.assertEquals(ObservedIssueKindOptions.ERROR, KindVO.tryFrom("ERROR").getKind());
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom(null));
    Assertions.assertEquals(ObservedIssueKindOptions.ERROR,
        KindVO.from(ObservedIssueKindOptions.ERROR).getKind());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedIssueKindOptions.ERROR + "]",
        KindVO.from(ObservedIssueKindOptions.ERROR).toString());
  }
}
